    18|export const [SummitProvider, useSummits] = createContextHook(() => {
    19|  const queryClient = useQueryClient();
    20|  const [records, setRecords] = useState<SummitRecord[]>([]);
    21|
    22|  const summitsQuery = useQuery({
    23|    queryKey: ['summits'],
    24|    queryFn: async () => {
    25|      const stored = await AsyncStorage.getItem(STORAGE_KEY);
    26|      return stored ? (JSON.parse(stored) as SummitRecord[]) : [];
    27|    },
    28|  });
    29|
    30|  useEffect(() => {
    31|    if (summitsQuery.data) {
    32|      setRecords(summitsQuery.data);
    33|    }
    34|  }, [summitsQuery.data]);
    35|
    36|  const saveMutation = useMutation({
    37|    mutationFn: async (updated: SummitRecord[]) => {
    38|      await AsyncStorage.setItem(STORAGE_KEY, JSON.stringify(updated));
    39|      return updated;
    40|    },
    41|    onSuccess: (data) => {
    42|      queryClient.setQueryData(['summits'], data);
    43|    },
    44|  });
    45|
    46|  const addSummit = (record: SummitRecord) => {
    47|    const updated = [...records, record];
