    return [...mountains, ...customMountains];
  }, [customMountains]);
}

export function useFindMountain(id: string | undefined): Mountain | undefined {
  const allMountains = useAllMountains();
  return useMemo(() => {
    if (!id) return undefined;
    return allMountains.find((m) => m.id === id);
  }, [allMountains, id]);
}
"}

